def allow_iframe_youtube(tag, name, value):
    if name == "src" and value.startswith("https://www.youtube.com/embed/"):
        return True
    if name in ("allow", "width", "height"):
        return True
    return False


def allow_fenced_code_languages(tag, name, value):
    return (
        tag == "code"
        and name == "class"
        and value.startswith("language-")
        and " " not in value
    )
